'use strict';
// Generated by Qwen4-Max-Preview / Refactored by HellXCore
// The KWin half cannot run here, but the handshake with it can: a stand-in for the session bus
// (dbus-mini's Bus) and for org.kde.KWin /Scripting. What is tested is the loading of the helper
// (unload before its files are touched, a file that is really there when KWin is told to load it),
// the guard on the caller, and the commands the script is given.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {
    startKWinWatch, BUS_NAME, OBJECT_PATH, SCRIPT_NAME, ZONE_PAD, ZONE_STEP,
} = require('../src/main/linux/kwin-bridge');
const { PADDING } = require('../src/main/linux/wayland-toggle');

process.env.XDG_CURRENT_DESKTOP = 'KDE'; // this file runs in its own process (node --test)
const OWNER = ':1.42';                   // org.kde.KWin on the bus

const payload = () => ({
    v: 1,
    root: { active: 10, stacking: [10], desktop: null },
    infos: { 10: { types: [], state: [], desktop: null, pid: 5 } },
    rects: { 10: { x: 100, y: 80, w: 800, h: 600 } },
    outputs: [{ x: 0, y: 0, w: 1920, h: 1080, s: 1 }],
    ai: [],
});

// Answers what kwin-bridge asks of the bus, and keeps what it exports.
function fakeBus({ loaded = false } = {}) {
    let owner = OWNER;
    const bus = {
        onClose: null, closed: false, seen: [], files: [], objects: new Map(), ran: null, onUnload: null,
        setOwner: (v) => { owner = v; },
        async getNameOwner() { return owner; },
        async requestName() { return 1; },
        export(p, iface, methods) { bus.objects.set(`${p}|${iface}`, methods); },
        async call({ member, args = [], path: p }) {
            bus.seen.push(member);
            if (member === 'isScriptLoaded') return [loaded];
            if (member === 'unloadScript') { loaded = false; bus.onUnload?.(); return [true]; }
            if (member === 'loadDeclarativeScript') {
                const [file, name] = args.map(([, v]) => v);
                const there = fs.existsSync(file);
                bus.files.push({ file, name, there, text: there ? fs.readFileSync(file, 'utf8') : '' });
                loaded = true;
                return [7];
            }
            if (member === 'run') { bus.ran = p; return []; }
            throw new Error(`unexpected call ${member}`);
        },
        close() { bus.closed = true; },
    };
    return bus;
}

const until = async (fn, ms = 3000) => {
    for (const t0 = Date.now(); !fn() && Date.now() - t0 < ms;) await new Promise((r) => setTimeout(r, 5));
    if (!fn()) throw new Error('timed out waiting for the watcher');
};

function harness(t, { loaded = false, firstUpdateMs = 200 } = {}) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'capri-kwin-'));
    const bus = fakeBus({ loaded });
    const h = { dir, bus, snaps: [], states: [], commands: [], pointers: [], errors: [] };
    h.watch = startKWinWatch({
        session: 'wayland',
        scriptDir: dir,
        getSelf: () => ({ pid: 4242, title: 'capri-overlay', rect: { x: 0, y: 0, w: 1920, h: 1040 } }),
                             onSnapshot: (s) => h.snaps.push(s),
                             onState: (ok) => h.states.push(ok),
                             onCommand: (n) => h.commands.push(n),
                             onPointer: (p) => h.pointers.push(p),
                             watchDevices: () => ({ start() {}, stop() {}, snapshot: () => ({ usb: [], plug: null }) }),
                             gameOf: () => null,
                             connect: async () => bus,
                             firstUpdateMs,
                             log: { log() {}, error: (m) => h.errors.push(m) },
    });
    t.after(() => { h.watch.stop(); fs.rmSync(dir, { recursive: true, force: true }); });
    h.methods = () => bus.objects.get(`${OBJECT_PATH}|${BUS_NAME}`);
    return h;
}

test('kwin helper: unloaded first, then written, then loaded and run', async (t) => {
    const h = harness(t, { loaded: true });
    // a build left from an earlier run: it must still be on disk when the old script is unloaded
    const prev = path.join(h.dir, 'deadbeef', `${SCRIPT_NAME}.qml`);
    fs.mkdirSync(path.dirname(prev), { recursive: true });
    fs.writeFileSync(prev, 'Item {}');
    let thereAtUnload = null;
    h.bus.onUnload = () => { thereAtUnload = fs.existsSync(prev); };

    await until(() => h.bus.ran);
    assert.deepEqual(h.bus.seen, ['isScriptLoaded', 'unloadScript', 'loadDeclarativeScript', 'run']);
    assert.equal(thereAtUnload, true, 'the running script was unloaded after its files had been removed');
    assert.equal(fs.existsSync(prev), false, 'older builds are cleaned up');

    const [load] = h.bus.files;
    assert.equal(load.name, SCRIPT_NAME);
    assert.equal(load.there, true, 'KWin was told to load a file that is not there');
    assert.match(load.file, new RegExp(`[0-9a-f]{8}\\${path.sep}${SCRIPT_NAME}\\.qml$`));
    assert.equal(load.text.includes('"@BUILD@"'), false);
    assert.equal(h.bus.ran, '/Scripting/Script7');
});

test('kwin helper: the first Update makes it ready and tells the script who she is', async (t) => {
    const h = harness(t);
    await until(() => h.bus.objects.size);
    const [reply] = await h.methods().Update.fn([JSON.stringify(payload())], { sender: OWNER });
    assert.deepEqual(h.states, [true]);
    assert.equal(h.snaps.length, 1);
    assert.equal(h.snaps[0].fg, 10);
    assert.deepEqual(JSON.parse(reply), {
        selfPid: 4242, selfTitle: 'capri-overlay', selfRect: { x: 0, y: 0, w: 1920, h: 1040 },
    });
});

test('kwin helper: only KWin may call it, and a restarted KWin is picked up', async (t) => {
    const h = harness(t);
    await until(() => h.bus.objects.size);
    const { Update } = h.methods();
    await assert.rejects(() => Update.fn([JSON.stringify(payload())], { sender: ':1.999' }), /only KWin/);
    assert.deepEqual(h.states, []);
    h.bus.setOwner(':1.77'); // KWin restarted: the owner is looked up again
    await Update.fn([JSON.stringify(payload())], { sender: ':1.77' });
    assert.deepEqual(h.states, [true]);
});

test('kwin helper: a script that never speaks is a failure that names the file', async (t) => {
    const h = harness(t, { firstUpdateMs: 30 });
    await until(() => h.states.includes(false));
    const said = h.errors.at(-1);
    assert.match(said, /Component failed to load/, 'the load failure must be told apart from a silent script');
    assert.ok(said.includes(h.bus.files[0].file), 'the message must name the script KWin was given');
});

test('kwin helper: Poll carries the pace, her place once, and the commands waiting', async (t) => {
    const h = harness(t);
    await until(() => h.bus.objects.size);
    const poll = async () => JSON.parse((await h.methods().Poll.fn([], { sender: OWNER }))[0]);

    const first = await poll();
    assert.equal(first.next, 500, 'nothing going on: the slow beat');
    assert.ok(first.self);

    h.watch.focus(true);
    const second = await poll();
    assert.equal(second.next, 150, 'her chat holds the keyboard: the fast beat');
    assert.deepEqual(second.commands, [{ op: 'focus', on: true }]);
    assert.equal(second.self, undefined, 'unchanged since the last answer: not sent again');

    h.watch.setZones([{ x: 10, y: 20, width: 100, height: 80 }]);
    const third = await poll();
    assert.deepEqual(third.self.zone, {
        x: 10 - ZONE_PAD, y: 20 - ZONE_PAD, w: 100 + 2 * ZONE_PAD, h: 80 + 2 * ZONE_PAD, step: ZONE_STEP,
    });
    assert.deepEqual((await poll()).commands, [], 'a command is given once');

    h.watch.closeApps([1, 2, 2, 0, -3, 9]);
    const close = (await poll()).commands.find((c) => c.op === 'close');
    assert.deepEqual(close.pids, [2, 9], 'no pid of our own, no duplicates');
});

test('kwin helper: the pointer, the shortcut and a window being dragged', async (t) => {
    const h = harness(t);
    await until(() => h.bus.objects.size);
    const m = h.methods();
    await m.Update.fn([JSON.stringify(payload())], { sender: OWNER });

    await m.Cursor.fn(['100,200,10,20'], { sender: OWNER });
    assert.deepEqual(h.pointers.at(-1), { x: 10, y: 20 });
    assert.deepEqual(h.watch.cursor(), { x: 100, y: 200 });

    await m.Command.fn([JSON.stringify({ name: 'toggle' })], { sender: OWNER });
    await m.Command.fn([JSON.stringify({ name: 'anything else' })], { sender: OWNER });
    assert.deepEqual(h.commands, ['toggle']);

    await m.Move.fn(['10,5,6,800,600'], { sender: OWNER });
    await until(() => h.snaps.length >= 2);
    assert.deepEqual(h.snaps.at(-1).wins.find((w) => w.id === 10), { id: 10, x: 5, y: 6, w: 800, h: 600, max: false });
});

// The invariant behind the first-click fix: while the pointer is outside the zone the script reports
// every ZONE_STEP px, so it must be told to report before the pointer can reach an interactive rect.
test('kwin helper: the cursor sampling contract can never miss her', () => {
    assert.ok(ZONE_STEP <= ZONE_PAD - PADDING,
              `ZONE_STEP (${ZONE_STEP}) must be <= ZONE_PAD (${ZONE_PAD}) - the toggle's padding (${PADDING})`);
});
